let data = null;
let direction = 'outbound';
let routeId = 'local';
let selectedTrainNo = null;
const routes = { local: { label: '吉安 → 瑞穗', from: '吉安', to: '瑞穗', weather: ['吉安鄉', '瑞穗鄉', '花蓮市'] }, 'hualien-taipei': { label: '花蓮 → 臺北', from: '花蓮', to: '臺北', weather: ['花蓮市'] }, 'hualien-luodong': { label: '花蓮 → 羅東', from: '花蓮', to: '羅東', weather: ['花蓮市'] } };
const $ = id => document.getElementById(id);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[c]);
const stationName = s => String(s ?? '').replace(/^\d+-/, '');
const taipei = d => new Intl.DateTimeFormat('sv-SE', { timeZone:'Asia/Taipei', year:'numeric', month:'2-digit', day:'2-digit' }).format(d);
const stamp = t => t ? new Date(t).toLocaleString('zh-TW', { timeZone:'Asia/Taipei', hour12:false }) : '尚無資料';
const age = t => t ? (Date.now() - Date.parse(t)) / 60000 : Infinity;
const parseMinutes = s => { const m = String(s || '').match(/(\d{2}):(\d{2})/); return m ? Number(m[1]) * 60 + Number(m[2]) : 9999; };
const normalizeStation = s => String(s || '').trim().replaceAll('台北', '臺北').replace(/[市縣鄉鎮區]$/, '');
const statusText = t => t?.lastReported ? `官方動態：${t.lastReported.name} ${t.lastReported.status}` : t?.status ? `官方動態：${t.status}` : t?.statusCheckedAt ? '官方已查詢：暫無準誤點回報' : '尚未取得官方動態';
const statusTone = t => { const value = String(t?.status || t?.lastReported?.status || '').trim(); return !value ? (t?.statusCheckedAt ? 'checked' : 'unknown') : /誤點|停駛|取消/.test(value) ? 'bad' : /準點|正常/.test(value) ? 'good' : 'checked'; };
const officialPosition = t => t?.lastReported && /到站|發車|運轉/.test(t.lastReported.status || '') ? t.lastReported : null;
function nowMinutes(){const p=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());return Number(p.find(x=>x.type==='hour')?.value||0)*60+Number(p.find(x=>x.type==='minute')?.value||0)}
function active(){const date=$('date').value,source=data?.days?.[date],profile=routes[routeId],route=source?.routes?.find(r=>r.id===routeId&&r.direction===direction),rows=routeId==='local'?source?.trains?.filter(t=>t.direction===direction)||[]:route?.trains||[];return {date,source,profile,route,rows}}
function setRouteByInputs(){const from=normalizeStation($('from').value),to=normalizeStation($('to').value);let match=Object.entries(routes).find(([,r])=>normalizeStation(r.from)===from&&normalizeStation(r.to)===to);if(match){routeId=match[0];direction='outbound'}else{match=Object.entries(routes).find(([,r])=>normalizeStation(r.to)===from&&normalizeStation(r.from)===to);if(match){routeId=match[0];direction='inbound'}}if(!match)routeId='custom';selectedTrainNo=null;for(const x of ['outbound','inbound'])$(x).setAttribute('aria-pressed',String(x===direction))}
function routeButtons(){const box=$('saved-routes');box.innerHTML=Object.entries(routes).map(([id,r])=>`<button type="button" data-route="${id}">${r.from} → ${r.to}</button>`).join('');for(const b of box.querySelectorAll('button'))b.onclick=()=>{routeId=b.dataset.route;direction='outbound';selectedTrainNo=null;$('from').value=routes[routeId].from;$('to').value=routes[routeId].to;for(const x of ['outbound','inbound'])$(x).setAttribute('aria-pressed',String(x===direction));render()}}
function statusMarkup(t,stale=false){const tone=stale?'unknown':statusTone(t),text=stale?'動態資料已過期':statusText(t),label={bad:'誤點提醒',good:'官方正常',checked:'官方已查',unknown:'等待資料'}[tone];return `<div class="status-line ${tone}"><span class="status-chip"><i></i>${label}</span><strong>${esc(text)}</strong>${t?.statusCheckedAt?`<small>動態取回 ${esc(stamp(t.statusCheckedAt))}</small>`:''}</div>`}
function trainUrl(no,date){return `https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip112/querybytrainno?rideDate=${date.replaceAll('-','/')}&trainNo=${encodeURIComponent(no)}`}
function trainState(train,date,minutes){const marks=train?.milestones||[],today=date===taipei(new Date()),inMotion=today&&parseMinutes(train?.departure)<=minutes&&minutes<parseMinutes(train?.arrival),official=today?officialPosition(train):null;let index=official?.name?marks.findIndex(m=>m.name===official.name):-1,estimated=false;if(index<0&&inMotion){index=marks.reduce((last,m,i)=>parseMinutes(m.departure||m.arrival)<=minutes?i:last,-1);estimated=index>=0}const ratio=!today?0:Math.max(0,Math.min(1,(minutes-parseMinutes(train?.departure))/Math.max(1,parseMinutes(train?.arrival)-parseMinutes(train?.departure))));return {inMotion,official,index,estimated,ratio,marks}}
function milestonesMarkup(train,date,minutes){const state=trainState(train,date,minutes);if(!state.marks.length)return '';const location=date!==taipei(new Date())?'本日行程站點':state.official?.name?`官方定位：${state.official.name}`:state.inMotion?'時刻推估位置（非官方定位）':minutes<parseMinutes(train.departure)?'尚未出發':'本日已到站';return `<div class="route-journey"><div class="route-journey-head"><span>${esc(location)}</span><span>左右滑動看完整站點</span></div><div class="route-journey-body"><button class="route-nav" type="button" data-route-scroll="prev" aria-label="查看前面的站">‹</button><div class="route-scroll" tabindex="0" aria-label="${esc(train.type||'列車')} ${esc(train.no||'')} 完整停靠站">${state.marks.map((m,i)=>`<span class="route-stop ${i===state.index?'train-here':''} ${state.estimated&&i===state.index?'estimated-position':''} ${m.status?'has-status':''}"><i></i>${i===state.index?`<em class="${state.estimated?'estimated':''}" aria-label="${state.estimated?'依時刻推估列車位置':'官方列車位置'}">🚆</em>`:''}<b>${esc(m.name)}</b><small>${esc(m.departure||m.arrival||'—')}</small>${m.status?`<u>${esc(m.status)}</u>`:''}</span>`).join('')}</div><button class="route-nav" type="button" data-route-scroll="next" aria-label="查看後面的站">›</button></div></div>`}
function nearbyRows(rows,focus){const i=Math.max(0,rows.findIndex(t=>t.no===focus?.no));return rows.slice(Math.max(0,i-1),Math.max(0,i-1)+Math.min(4,rows.length))}
function compactStatus(t){return `<span class="mini-status ${statusTone(t)}">${esc(String(t?.status||t?.lastReported?.status||'未回報'))}</span>`}
function pickerMarkup(trains,focus){return trains.length?trains.map(t=>`<button type="button" class="train-choice ${t.no===focus?.no?'selected':''}" data-select-train="${esc(t.no)}" aria-pressed="${t.no===focus?.no}"><span>${esc(t.type)}</span><b>${esc(t.no)}</b><strong>${esc(t.departure)} <i>→</i> ${esc(t.arrival)}</strong>${compactStatus(t)}</button>`).join(''):'<p class="no-data">這個日期尚無可用班次。</p>'}
function timelineMarkup(trains,focus,date,minutes){if(!trains.length)return '';return `<div class="timeline-head"><span>相鄰班次同時比較</span><span>🚆 代表依時刻的行程進度</span></div><div class="timeline-list">${trains.map(t=>{const s=trainState(t,date,minutes),phase=date!==taipei(new Date())?'預定':s.inMotion?'行駛中':minutes<parseMinutes(t.departure)?'尚未出發':'已抵達';return `<button type="button" class="timeline-train ${t.no===focus?.no?'selected':''}" data-select-train="${esc(t.no)}"><span class="timeline-label"><b>${esc(t.no)}</b><small>${esc(t.departure)} → ${esc(t.arrival)}</small></span><span class="timeline-track" style="--progress:${Math.round(s.ratio*100)}%"><i></i><em class="${s.inMotion?'moving':''}">🚆</em></span><span class="timeline-state ${statusTone(t)}">${esc(phase)}<small>${esc(String(t.status||t.lastReported?.status||'未回報'))}</small></span></button>`}).join('')}</div>`}
function weatherNameFor(train,date,minutes){const s=trainState(train,date,minutes);if(routeId==='local'){if(stationName(train.to)==='花蓮')return '花蓮市';if(!s.inMotion||s.ratio<.52)return direction==='outbound'?'吉安鄉':'瑞穗鄉';return direction==='outbound'?'瑞穗鄉':'吉安鄉'}return routes[routeId]?.weather?.[0]||'花蓮市'}
function closestForecast(name,date,minutes){const weather=data.weather?.[name],choices=weather?.hours?.filter(h=>h.date===date)||[];return {weather,hour:choices.sort((a,b)=>Math.abs(parseMinutes(a.time)-minutes)-Math.abs(parseMinutes(b.time)-minutes))[0]}}
function weatherCard(name,label,date,minutes,active=false){const {weather,hour}=closestForecast(name,date,minutes);return `<article class="weather-stop ${active?'visible moving':''}"><div class="weather-stop-index">${active?'🚆':'○'}</div><div><b>${esc(label)}</b><small>${esc(name)}預報 · ${weather?`取回 ${stamp(weather.checkedAt)}`:'等待下一輪擷取'}</small></div><div class="weather-main">${hour?`<strong>${esc(hour.temperature)}°</strong><span>${esc(hour.description||'天氣狀況未提供')}<br>雨 ${esc(hour.rain||'未提供')} · 風 ${esc(hour.wind||'未提供')}</span>`:'<span>目前尚無此段預報</span>'}</div></article>`}
function enableRouteScrollers(){document.querySelectorAll('[data-route-scroll]').forEach(b=>b.onclick=()=>{const s=b.parentElement.querySelector('.route-scroll');s.scrollBy({left:(b.dataset.routeScroll==='next'?1:-1)*Math.max(220,s.clientWidth*.72),behavior:'smooth'})});document.querySelectorAll('.route-scroll').forEach(s=>{let x=0,y=0,left=0;s.addEventListener('touchstart',e=>{const t=e.touches[0];x=t.clientX;y=t.clientY;left=s.scrollLeft},{passive:true});s.addEventListener('touchmove',e=>{const t=e.touches[0],dx=t.clientX-x,dy=t.clientY-y;if(Math.abs(dx)>Math.abs(dy)){e.preventDefault();s.scrollLeft=left-dx}},{passive:false});const here=s.querySelector('.train-here');if(here)requestAnimationFrame(()=>here.scrollIntoView({block:'nearest',inline:'center'}))})}
function enableTrainSelection(){document.querySelectorAll('[data-select-train]').forEach(b=>b.onclick=()=>{selectedTrainNo=b.dataset.selectTrain;render();requestAnimationFrame(()=>$('selected-train')?.scrollIntoView({behavior:'smooth',block:'start'}))})}
function render(){if(!data)return;const {date,source,profile,route,rows}=active(),stale=age(route?.checkedAt||source?.checkedAt)>15,custom=routeId==='custom',origin=custom?$('from').value:direction==='outbound'?profile.from:profile.to,destination=custom?$('to').value:direction==='outbound'?profile.to:profile.from;if(!custom){$('from').value=origin;$('to').value=destination}const corridor=routeId==='hualien-taipei'?(direction==='outbound'?'臺東・花蓮 → 臺北':'臺北 → 花蓮・臺東'):routeId==='hualien-luodong'?(direction==='outbound'?'花蓮 → 宜蘭・羅東':'羅東・宜蘭 → 花蓮'):null;$('journey-title').textContent=custom?`${$('from').value||'起點'} → ${$('to').value||'終點'}`:corridor||`${origin} → ${destination}`;$('freshness').textContent=source?`列車資料取回：${stamp(route?.checkedAt||source.checkedAt)}${stale?' ｜已過期，請以台鐵公告為準。':' ｜每 10 分鐘向台鐵更新；頁面每分鐘讀取一次。'}`:'這個日期尚未取得資料，請換日期或等待下一輪自動更新。';$('rail-status').textContent=`${data.rail?.text||'尚未取得路線公告'} · ${stamp(data.rail?.checkedAt)}`;$('mode-note').textContent=custom?'這條路線尚未建立自動擷取設定；目前可直接使用三條常用路線。':'選一班車後，下方只保留它的官方動態、完整站序與沿線天氣。灰色小火車是時刻推估，官方沒有提供 GPS 位置。';const mins=nowMinutes(),today=date===taipei(new Date()),running=today?rows.filter(t=>parseMinutes(t.departure)<=mins&&mins<parseMinutes(t.arrival)):[],defaultFocus=running[0]||rows.find(t=>parseMinutes(t.departure)>mins)||rows[0]||null,focus=rows.find(t=>t.no===selectedTrainNo)||defaultFocus;if(selectedTrainNo&&!rows.some(t=>t.no===selectedTrainNo))selectedTrainNo=null;const nearby=nearbyRows(rows,focus);$('collection-info').textContent=`${rows.length} 班已整理 · ${stale?'動態已過期':'可點選切換'}`;$('train-picker').innerHTML=pickerMarkup(nearby,focus);$('route-timeline').innerHTML=timelineMarkup(nearby,focus,date,mins);if(focus){const state=trainState(focus,date,mins),current=state.marks[state.index]?.name||stationName(focus.from),weatherName=weatherNameFor(focus,date,mins),forecast=closestForecast(weatherName,date,mins),location=state.inMotion?`小火車現在在${state.official?.name?` ${state.official.name}`:` ${current} 附近`}`:mins<parseMinutes(focus.departure)?`預計從 ${stationName(focus.from)} 出發`:`已抵達 ${stationName(focus.to)}`;$('selected-train').innerHTML=`<div class="selected-head"><div><p class="kicker">SELECTED TRAIN</p><h3>${esc(focus.type)} ${esc(focus.no)}</h3></div><div class="selected-times"><b>${esc(focus.departure)} → ${esc(focus.arrival)}</b><small>${esc(stationName(focus.from))} → ${esc(stationName(focus.to))}</small></div></div>${statusMarkup(focus,stale)}<div class="moving-weather-card"><span>☁</span><div><b>${esc(location)}</b><small>行駛路段採最近可用的 ${esc(weatherName)} 逐 3 小時預報</small></div><strong>${forecast.hour?`${esc(forecast.hour.description||'天氣')} ${esc(forecast.hour.temperature)}°`:'預報待更新'}</strong></div>${milestonesMarkup(focus,date,mins)}<a class="official-link" href="${trainUrl(focus.no,date)}" target="_blank" rel="noopener">查看台鐵官方逐站動態 ↗</a>`;const endWeather=stationName(focus.to)==='花蓮'?'花蓮市':direction==='outbound'?'瑞穗鄉':'吉安鄉',weatherNames=[...new Set([weatherName,endWeather,'花蓮市'])];$('weather').innerHTML=weatherNames.map((name,i)=>weatherCard(name,i===0?`${current} 行駛路段`:i===1?`${stationName(focus.to)} 抵達前後`:'花蓮端',date,mins,i===0)).join('');$('weather-note').textContent=`${current} 路段已標示`}else{$('selected-train').innerHTML='<div class="no-data">尚無這條路線的本日資料。</div>';$('weather').innerHTML='';$('weather-note').textContent='沿線預報'}enableTrainSelection();enableRouteScrollers()}
async function refresh(){try{const r=await fetch(`data.json?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw Error();data=await r.json();if(!$('date').dataset.chosen){const now=new Date(),today=taipei(now),h=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',hour12:false}).format(now));$('date').value=data.days?.[today]?today:Object.keys(data.days||{}).sort().at(-1)||today;direction=h>=12?'inbound':'outbound'}render();return true}catch{$('freshness').textContent='資料讀取失敗，請稍後再試。';return false}}
routeButtons();$('date').value=taipei(new Date());$('trip-form').onsubmit=e=>{e.preventDefault();setRouteByInputs();$('date').dataset.chosen='true';render()};$('swap').onclick=()=>{const a=$('from').value;$('from').value=$('to').value;$('to').value=a;setRouteByInputs();render()};for(const id of ['outbound','inbound'])$(id).onclick=()=>{direction=id;selectedTrainNo=null;for(const x of ['outbound','inbound'])$(x).setAttribute('aria-pressed',String(x===id));render()};$('date').onchange=()=>{$('date').dataset.chosen='true';selectedTrainNo=null;render()};$('reload-data').onclick=async()=>{const b=$('reload-data'),before=data?.attemptedAt;b.disabled=true;b.textContent='讀取中…';const ok=await refresh(),after=data?.attemptedAt;b.textContent=ok?(after&&after!==before?'✓ 已取得新快照':'✓ 已讀取現有快照'):'↻ 再試一次';setTimeout(()=>{b.disabled=false;b.textContent='↻ 重新讀取快照'},1800)};setInterval(()=>{$('clock').textContent=stamp(new Date().toISOString())},1000);setInterval(()=>{if(!document.hidden)refresh()},60000);refresh();
